//! EUC-JP, built in (no charmap file needed): JIS X 0208 and JIS X 0212 from the WHATWG Encoding
//! Standard indexes (`jis_tables`, generated by `cargo xtask encodings-gen`), in the variant the
//! reference library converts, as probed over its whole code space.
//!
//! **Bytes.** 0x00..=0x7F are ASCII and 0x80..=0x8D, 0x90..=0x9F the C1 controls, one byte each;
//! 0x8E then 0xA1..=0xDF is a half-width katakana (U+FF61..=U+FF9F); two bytes 0xA1..=0xFE are a
//! JIS X 0208 character (row, cell); 0x8F then two such bytes a JIS X 0212 character.
//!
//! **Variant (probed).** Of the index's JIS X 0208, row 13 and rows 89..=92 (the vendor
//! extensions) are absent, and six cells map to other code points ([`JIS0208_CELLS`]).
//! U+00A5 and U+203E encode to 0x5C and 0x7E, one way. The tag characters U+E0000..=U+E007F encode
//! to nothing. A code point both sets have is written in JIS X 0208.
//!
//! **Invalid input (probed).** A lead byte 0xA0..=0xFE or 0x8E followed by a byte that ends no
//! character is invalid; `//IGNORE` skips the lead alone when that byte is below 0xA0 (ASCII or
//! a C1 control, read again as a character), else both.
//! After 0x8F only 0xA2..=0xED (the rows JIS X 0212 spans) wait for a third byte; any invalid
//! sequence starting 0x8F skips the 0x8F alone. 0xFF is invalid.

#![allow(clippy::arithmetic_side_effects)] // bytes and pointers below 94 * 94

use super::Dec;
use super::jis_tables::{JIS0208, JIS0208_CPS, JIS0208_PTRS, JIS0212, JIS0212_CPS, JIS0212_PTRS};

/// JIS X 0208 cells whose code point is not the index's: (pointer, code point).
const JIS0208_CELLS: [(usize, u32); 6] = [(32, 0x301C), (33, 0x2016), (60, 0x2212), (80, 0x00A2), (81, 0x00A3), (94 + 43, 0x00AC)];

/// The JIS X 0208 character of pointer `p` in this variant (0: none).
fn jis0208(p: usize) -> u32 {
    let row = p / 94;
    if row == 12 || (88..=91).contains(&row) {
        return 0;
    }
    if p <= 94 + 43 {
        if let Some(&(_, c)) = JIS0208_CELLS.iter().find(|&&(q, _)| q == p) {
            return c;
        }
    }
    JIS0208.get(p).map_or(0, |&c| u32::from(c))
}

/// The JIS X 0212 character of pointer `p` (0: none).
fn jis0212(p: usize) -> u32 {
    JIS0212.get(p).map_or(0, |&c| u32::from(c))
}

/// The pointer of row byte `r` and cell byte `c` (both 0xA1..=0xFE).
fn pointer(r: u8, c: u8) -> Option<usize> {
    let ok = |b: u8| (0xA1..=0xFE).contains(&b);
    (ok(r) && ok(c)).then(|| usize::from(r - 0xA1) * 94 + usize::from(c - 0xA1))
}

/// Bytes `//IGNORE` skips when the byte after a lead ends no character.
fn skip(second: u8) -> usize {
    if second < 0xA0 { 1 } else { 2 }
}

/// Decode one character.
pub(super) fn decode(input: &[u8]) -> Dec {
    let Some(&b0) = input.first() else { return Dec::Incomplete };
    match b0 {
        0x00..=0x8D | 0x90..=0x9F => Dec::Char(u32::from(b0), 1),
        0xFF => Dec::Invalid(1),
        0x8E => match input.get(1) {
            None => Dec::Incomplete,
            Some(&b1 @ 0xA1..=0xDF) => Dec::Char(0xFF61 + u32::from(b1 - 0xA1), 2),
            Some(&b1) => Dec::Invalid(skip(b1)),
        },
        0x8F => match (input.get(1), input.get(2)) {
            (None, _) => Dec::Incomplete,
            (Some(&b1), _) if !(0xA2..=0xED).contains(&b1) => Dec::Invalid(1),
            (Some(_), None) => Dec::Incomplete,
            (Some(&b1), Some(&b2)) => match pointer(b1, b2).map(jis0212) {
                Some(c) if c != 0 => Dec::Char(c, 3),
                _ => Dec::Invalid(1),
            },
        },
        0xA0..=0xFE => match input.get(1) {
            None => Dec::Incomplete,
            Some(&b1) => match pointer(b0, b1).map(jis0208) {
                Some(c) if c != 0 => Dec::Char(c, 2),
                _ => Dec::Invalid(skip(b1)),
            },
        },
    }
}

/// The first pointer of `c` in a set's encode arrays that `ok` accepts.
fn find(cps: &[u16], ptrs: &[u16], c: u16, ok: impl Fn(usize) -> bool) -> Option<usize> {
    let start = cps.partition_point(|&x| x < c);
    let (cps, ptrs) = (cps.get(start..)?, ptrs.get(start..)?);
    cps.iter().zip(ptrs).take_while(|&(&x, _)| x == c).map(|(_, &p)| usize::from(p)).find(|&p| ok(p))
}

/// Write `bytes` to the front of `out`.
fn put(out: &mut [u8; 8], bytes: &[u8]) -> Option<usize> {
    out.get_mut(..bytes.len())?.copy_from_slice(bytes);
    Some(bytes.len())
}

/// The two bytes of pointer `p` (row, cell from 0xA1).
fn pair(p: usize) -> [u8; 2] {
    let b = |v: usize| u8::try_from(0xA1 + v).unwrap_or(0);
    [b(p / 94), b(p % 94)]
}

/// Encode `c`; `None` if EUC-JP has no character for it.
pub(super) fn encode(c: u32, out: &mut [u8; 8]) -> Option<usize> {
    match c {
        0x00..=0x8D | 0x90..=0x9F => return put(out, &[u8::try_from(c).ok()?]),
        0xA5 => return put(out, b"\\"),
        0x203E => return put(out, b"~"),
        0xFF61..=0xFF9F => return put(out, &[0x8E, u8::try_from(c - 0xFF61 + 0xA1).ok()?]),
        0xE0000..=0xE007F => return Some(0),
        _ => {}
    }
    let c16 = u16::try_from(c).ok()?;
    if let Some(p) = find(&JIS0208_CPS, &JIS0208_PTRS, c16, |p| jis0208(p) == c) {
        return put(out, &pair(p));
    }
    if let Some(&(p, _)) = JIS0208_CELLS.iter().find(|&&(_, x)| x == c) {
        return put(out, &pair(p));
    }
    let p = find(&JIS0212_CPS, &JIS0212_PTRS, c16, |p| jis0212(p) == c)?;
    let [r, k] = pair(p);
    put(out, &[0x8F, r, k])
}

#[cfg(test)]
#[allow(clippy::indexing_slicing, clippy::unwrap_used)]
mod tests {
    use super::*;

    fn enc(c: u32) -> Option<Vec<u8>> {
        let mut out = [0u8; 8];
        encode(c, &mut out).map(|n| out[..n].to_vec())
    }

    /// The variant's cells, as probed (spec §6.4, s6_4_c_2): the remapped JIS X 0208 cells, the
    /// rows left out, the one-way encodings, and which set a shared code point is written in.
    #[test]
    fn euc_jp_variant_cells() {
        assert_eq!(decode(&[0xA1, 0xC1]), Dec::Char(0x301C, 2));
        assert_eq!(decode(&[0xA2, 0xCC]), Dec::Char(0x00AC, 2));
        assert_eq!(decode(&[0xAD, 0xA1]), Dec::Invalid(2), "row 13 is not in this variant");
        assert_eq!(decode(&[0xF9, 0xA1]), Dec::Invalid(2), "rows 89..=92 are not in this variant");
        assert_eq!(decode(&[0x8F, 0xA2, 0xB7]), Dec::Char(0xFF5E, 3));
        assert_eq!(decode(&[0x8E, 0xDF]), Dec::Char(0xFF9F, 2));
        assert_eq!(decode(&[0x8D]), Dec::Char(0x8D, 1));
        assert_eq!(enc(0xFF5E), Some(vec![0x8F, 0xA2, 0xB7]));
        assert_eq!(enc(0x301C), Some(vec![0xA1, 0xC1]));
        assert_eq!(enc(0x00E9), Some(vec![0x8F, 0xAB, 0xB1]));
        assert_eq!(enc(0xA5), Some(vec![0x5C]));
        assert_eq!(enc(0xE0001), Some(vec![]));
        assert_eq!(enc(0x8E), None);
        assert_eq!(enc(0x20AC), None);
    }

    /// Incomplete and invalid input, and how far `//IGNORE` skips (s6_4_f_2_2, s6_4_f_2_3,
    /// s6_4_f_3).
    #[test]
    fn euc_jp_invalid_input() {
        assert_eq!(decode(&[0xA1]), Dec::Incomplete);
        assert_eq!(decode(&[0x8F, 0xA2]), Dec::Incomplete);
        assert_eq!(decode(&[0xA1, 0x41]), Dec::Invalid(1));
        assert_eq!(decode(&[0xA1, 0xFF]), Dec::Invalid(2));
        assert_eq!(decode(&[0x8E, 0xE0]), Dec::Invalid(2));
        assert_eq!(decode(&[0x8E, 0x9F]), Dec::Invalid(1), "a C1 control after a lead is read again");
        assert_eq!(decode(&[0xA2, 0x80]), Dec::Invalid(1));
        assert_eq!(decode(&[0xA2, 0xA0]), Dec::Invalid(2));
        assert_eq!(decode(&[0x8F, 0xA1]), Dec::Invalid(1), "row 1 is outside JIS X 0212's rows");
        assert_eq!(decode(&[0x8F, 0xA2, 0xA1]), Dec::Invalid(1));
        assert_eq!(decode(&[0xFF]), Dec::Invalid(1));
    }

    /// Every character decodes and encodes back to itself (s6_4_c_2): as many as the reference
    /// decodes (13167, probed), each written as the sequence it was read from.
    #[test]
    fn euc_jp_round_trips() {
        let mut n = 0;
        let ones = (0..=0xFFu8).map(|a| vec![a]);
        let twos = (0..=0xFFFFu16).map(|v| v.to_be_bytes().to_vec());
        for seq in ones.chain(twos) {
            for s in [seq.clone(), [vec![0x8F], seq].concat()] {
                if let Dec::Char(c, len) = decode(&s) {
                    if len == s.len() {
                        assert_eq!(enc(c).as_deref(), Some(&s[..]), "U+{c:04X}");
                        n += 1;
                    }
                }
            }
        }
        assert_eq!(n, 13167, "the characters the reference decodes");
    }
}
